#include "capped-reuse-pool.h"
#include <stdexcept>
namespace reuse_pool {Pool::Pool(std::size_t n):slots_(n){}std::optional<Handle> Pool::acquire(){for(std::size_t i=0;i<slots_.size();++i)if(slots_[i].state==Slot::free){slots_[i].state=Slot::live;++slots_[i].generation;++live_;return Handle{i,slots_[i].generation};}return std::nullopt;}void Pool::release(Handle h){if(h.index>=slots_.size())throw std::out_of_range("handle");auto& s=slots_[h.index];if(s.state!=Slot::live||s.generation!=h.generation)throw std::invalid_argument("stale handle");s.state=Slot::retired;--live_;}std::size_t Pool::collect(std::size_t budget){std::size_t freed=0;if(slots_.empty())return 0;for(std::size_t n=0;n<budget;++n){auto& s=slots_[cursor_];if(s.state==Slot::retired){s.state=Slot::free;++freed;}cursor_=(cursor_+1)%slots_.size();}return freed;}std::size_t Pool::live()const noexcept{return live_;}}
